function doStuff()
{
   flagpolestates_mc.flagpole_mc.candyholder_mc.gotoAndStop(2);
   flagpolestates_mc.flagpole_mc.gotoAndPlay(110);
   SHELL.setHuntItemAsFoundById(0);
}
function onHuntChanged(obj)
{
   INTERFACE.showContent("halloween_hunt");
}
function handleThrow(mc)
{
   if(mc._x > 660 && mc._x < 685)
   {
      if(mc._y > 61 && mc._y < 93)
      {
         if(clocktower.tower._currentframe == 1)
         {
            clocktower.tower.play();
         }
         mc._visible = false;
      }
   }
}
function clockTimer()
{
   now.setTime(now.getTime() + 1000);
   ct_day = now.getDay();
   if(ct_day == 0)
   {
      clocktower.day_txt.text = "SUNDAY";
   }
   else if(ct_day == 1)
   {
      clocktower.day_txt.text = "MONDAY";
   }
   else if(ct_day == 2)
   {
      clocktower.day_txt.text = "TUESDAY";
   }
   else if(ct_day == 3)
   {
      clocktower.day_txt.text = "WEDNESDAY";
   }
   else if(ct_day == 4)
   {
      clocktower.day_txt.text = "THURSDAY";
   }
   else if(ct_day == 5)
   {
      clocktower.day_txt.text = "FRIDAY";
   }
   else if(ct_day == 6)
   {
      clocktower.day_txt.text = "SATURDAY";
   }
   ct_hours = now.getHours();
   if(ct_hours > 11)
   {
      if(ct_hours > 12)
      {
         ct_hours -= 12;
      }
      pm_trigger = true;
   }
   else
   {
      if(ct_hours == 0)
      {
         ct_hours = 12;
      }
      pm_trigger = false;
   }
   if(pm_trigger == true)
   {
      clocktower.am_pm.text = "PM";
   }
   else
   {
      clocktower.am_pm.text = "AM";
   }
   ct_minutes = now.getMinutes();
   if(ct_minutes < 10)
   {
      ct_minutes = "0" + now.getMinutes();
   }
   clocktower.clock_txt.text = ct_hours + " : " + ct_minutes;
}
